inline const Info* Find(int id) {
    std::size_t lo = 0, hi = sizeof(kTable) / sizeof(kTable[0]);
    while (lo < hi) {
        std::size_t mid = (lo + hi) / 2;
        if (kTable[mid].id < id) lo = mid + 1; else hi = mid;
    }
    return (lo < sizeof(kTable) / sizeof(kTable[0]) && kTable[lo].id == id) ? &kTable[lo] : nullptr;
}

